#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Edge {
    long long dist_sq;
    int u, v;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> x(n + 1), y(n + 1);
    x[0] = 0;
    y[0] = 0;

    for (int i = 1; i <= n; ++i) {
        cin >> x[i] >> y[i];
    }

    size_t total_edges = (size_t)n * (n + 1) / 2;
    vector<Edge> edges;
    edges.reserve(total_edges);

    for (int i = 0; i <= n; ++i) {
        for (int j = i + 1; j <= n; ++j) {
            long long dx = x[i] - x[j];
            long long dy = y[i] - y[j];
            edges.push_back({dx * dx + dy * dy, i, j});
        }
    }

    sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) {
        return a.dist_sq > b.dist_sq;
    });

    vector<int> dp(n + 1, -1);
    dp[0] = 0;

    int ans = 0;
    vector<pair<int, int>> updates;

    size_t m = edges.size();
    for (size_t i = 0; i < m; ) {
        size_t j = i;
        while (j < m && edges[j].dist_sq == edges[i].dist_sq) {
            int u = edges[j].u;
            int v = edges[j].v;

            if (u == 0) {
                if (dp[0] != -1) {
                    updates.push_back({v, dp[0] + 1});
                }
            } else {
                if (dp[u] > 0) {
                    updates.push_back({v, dp[u] + 1});
                }
                if (dp[v] > 0) {
                    updates.push_back({u, dp[v] + 1});
                }
            }
            j++;
        }

        for (const auto& upd : updates) {
            if (upd.second > dp[upd.first]) {
                dp[upd.first] = upd.second;
                if (dp[upd.first] > ans) {
                    ans = dp[upd.first];
                }
            }
        }
        updates.clear();
        i = j;
    }

    cout << ans << "\n";

    return 0;
}
